-- Insert Derpartment is not exist from #tmpEmp
DECLARE @MaxGroupDeptId INT = (SELECT ISNULL(MAX(GroupDeptId), 0) FROM dbo.Department WITH(NOLOCK));
;WITH DistinctDepts AS (
	SELECT DISTINCT 
		t.DeptCode, 
		t.DeptName, 
		u.UnitId,
		1 AS IsActive,
		GETDATE() AS CreatedDate,
		0 AS IsDeleted,
		e.EmpId
	FROM #tmpEmp t
	INNER JOIN dbo.Company c WITH(NOLOCK) ON t.Company = c.Name
	LEFT JOIN dbo.Unit u WITH(NOLOCK) ON u.Code = t.BUCode
	LEFT JOIN dbo.Employee e WITH(NOLOCK) ON e.NickName = t.DeptPIC
	WHERE t.DeptCode NOT IN (SELECT Code FROM dbo.Department WITH(NOLOCK))
)
INSERT INTO dbo.Department(
    Code, Name, UnitId, IsActive, ModifiedDate, IsDeleted, GroupDeptId, PICEmpId
)
SELECT 
	DeptCode,
	DeptName,
	UnitId,
	IsActive,
	CreatedDate,
	IsDeleted,
	@MaxGroupDeptId + ROW_NUMBER() OVER (ORDER BY DeptCode) AS GroupDeptId,
	EmpId
FROM DistinctDepts;

-- Insert Team is not exist from #tmpEmp
DECLARE @MaxGroupId INT = (SELECT ISNULL(MAX(GroupTeamId), 0) FROM dbo.[Group]);
;WITH DistinctTeams AS (
		SELECT DISTINCT 
		t.TeamCode,  
		t.TeamName,
		d.DepartmentId,
		t.TeamPIC,
		t.CombineTeam,
		t.CompanyId,
		t.AccountableArea
	FROM #tmpEmp t
	LEFT JOIN dbo.Department d WITH(NOLOCK) ON d.Code = t.DeptCode 
)  
INSERT INTO dbo.[Group] (
    Code, Name, CreatedDate, IsDeleted, CompanyId,
	DepartmentId, AccountableArea, GroupTeamId, PICEmpId
)
SELECT
	t.TeamCode,
	t.TeamName,
	GETDATE(),
	0,
	t.CompanyId,
	t.DepartmentId,
	t.AccountableArea,
	@MaxGroupId + ROW_NUMBER() OVER (ORDER BY CombineTeam),
	emp.EmpId
FROM DistinctTeams t
LEFT JOIN (
	SELECT e.NickName, e.EmpId, ce.CompanyId
	FROM dbo.Employee e WITH(NOLOCK)
	INNER JOIN dbo.CompanyEmployee ce WITH(NOLOCK) ON ce.EmpId = e.EmpId
) AS emp ON emp.NickName = t.TeamPIC AND emp.CompanyId = t.CompanyId

---- Update GroupId in Employee table from #tmpEmp
UPDATE e
SET e.GroupId = g.GroupId
FROM dbo.Employee e WITH(NOLOCK)
INNER JOIN #tmpEmp t ON e.UserId = t.UserId
INNER JOIN (
	SELECT g.GroupId,
     g.Code + ' | ' + g.Name + ' | ' + d.Code + ' | ' + u.Code + ' | ' + c.Name AS CombineTeam
	FROM dbo.[Group] g WITH(NOLOCK)
	INNER JOIN dbo.Department d WITH(NOLOCK) ON d.DepartmentId = g.DepartmentId
    INNER JOIN dbo.Unit u WITH(NOLOCK) ON u.UnitId = d.UnitId
    INNER JOIN dbo.Company c WITH(NOLOCK) ON c.CompanyId = g.CompanyId
) AS g ON g.CombineTeam = t.CombineTeam

